[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0A0A0A;
      --bg-2: #111111;
      --bg-3: #1A1A1A;
      --border: rgba(255,255,255,0.08);
      --border-hover: rgba(255,255,255,0.18);
      --white: #FFFFFF;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --accent: #2563EB;
      --accent-hover: #3B82F6;
      --accent-light: rgba(37,99,235,0.15);
      --amber: #F59E0B;
      --radius: 4px;
      --radius-lg: 8px;
    }

    html { scroll-behavior: smooth; }

    body {
      background: var(--bg);
      color: var(--white);
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    /* ── SCROLLBAR ── */
    ::-webkit-scrollbar { width: 6px; height: 6px; }
    ::-webkit-scrollbar-track { background: var(--bg); }
    ::-webkit-scrollbar-thumb { background: var(--gray-600); border-radius: 3px; }

    /* ── UTILITIES ── */
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
    .container { max-width: 1320px; margin: 0 auto; padding: 0 24px; }
    @media (min-width: 768px) { .container { padding: 0 48px; } }

    .label {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--gray-400);
    }

    .section-title {
      font-size: clamp(2rem, 4vw, 3.25rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.02em;
    }

    .section-sub {
      font-size: 1.0625rem;
      color: var(--gray-400);
      max-width: 600px;
      line-height: 1.7;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 11px 24px;
      border-radius: var(--radius);
      font-size: 14px;
      font-weight: 600;
      letter-spacing: 0.01em;
      cursor: pointer;
      transition: all 0.2s ease;
      border: none;
      text-decoration: none;
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--white);
      color: #000;
    }
    .btn-primary:hover { background: #E5E7EB; }
    .btn-outline {
      background: transparent;
      color: var(--white);
      border: 1px solid var(--border-hover);
    }
    .btn-outline:hover { border-color: var(--white); background: rgba(255,255,255,0.05); }
    .btn-accent {
      background: var(--accent);
      color: var(--white);
    }
    .btn-accent:hover { background: var(--accent-hover); }

    .arrow-icon {
      width: 16px; height: 16px;
      display: inline-block;
      position: relative;
    }
    .arrow-icon::after {
      content: '→';
      font-size: 15px;
    }

    /* ── NAV ── */
    #nav {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 1000;
      border-bottom: 1px solid transparent;
      transition: border-color 0.3s, background 0.3s;
    }
    #nav.scrolled {
      background: rgba(10,10,10,0.92);
      backdrop-filter: blur(16px);
      border-color: var(--border);
    }
    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
      gap: 32px;
    }
    .nav-logo {
      font-size: 18px;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--white);
      text-decoration: none;
      flex-shrink: 0;
    }
    .nav-logo span { color: var(--accent); }

    .nav-links {
      display: none;
      align-items: center;
      gap: 32px;
      list-style: none;
    }
    @media (min-width: 1024px) { .nav-links { display: flex; } }
    .nav-links a {
      font-size: 13.5px;
      font-weight: 500;
      color: var(--gray-400);
      text-decoration: none;
      transition: color 0.2s;
      letter-spacing: 0.01em;
    }
    .nav-links a:hover { color: var(--white); }

    .nav-right {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    /* Language dropdown */
    .lang-dropdown { position: relative; }
    .lang-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      background: none;
      border: 1px solid var(--border);
      color: var(--gray-400);
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      padding: 7px 12px;
      border-radius: var(--radius);
      cursor: pointer;
      transition: all 0.2s;
      font-family: inherit;
    }
    .lang-btn:hover { color: var(--white); border-color: var(--border-hover); }
    .lang-btn svg { width: 10px; height: 10px; transition: transform 0.2s; }
    .lang-btn.open svg { transform: rotate(180deg); }
    .lang-menu {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--bg-3);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      min-width: 160px;
      overflow: hidden;
      opacity: 0;
      pointer-events: none;
      transform: translateY(-6px);
      transition: all 0.2s;
    }
    .lang-menu.open { opacity: 1; pointer-events: all; transform: translateY(0); }
    .lang-menu a {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 16px;
      font-size: 13px;
      color: var(--gray-400);
      text-decoration: none;
      transition: all 0.15s;
    }
    .lang-menu a:hover { background: rgba(255,255,255,0.05); color: var(--white); }
    .lang-menu a.active { color: var(--white); }

    .hamburger {
      display: flex;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 6px;
    }
    @media (min-width: 1024px) { .hamburger { display: none; } }
    .hamburger span {
      display: block;
      width: 22px;
      height: 1.5px;
      background: var(--white);
      border-radius: 2px;
      transition: all 0.25s;
    }

    /* Mobile menu */
    .mobile-menu {
      display: none;
      position: fixed;
      top: 68px; left: 0; right: 0; bottom: 0;
      background: var(--bg);
      z-index: 999;
      padding: 40px 24px;
      overflow-y: auto;
    }
    .mobile-menu.open { display: block; }
    .mobile-menu ul { list-style: none; }
    .mobile-menu ul li { border-bottom: 1px solid var(--border); }
    .mobile-menu ul li a {
      display: block;
      padding: 18px 0;
      font-size: 22px;
      font-weight: 700;
      color: var(--white);
      text-decoration: none;
    }

    /* ── HERO ── */
    #hero {
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      position: relative;
      overflow: hidden;
      padding-top: 68px;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, #0D1117 0%, #0A0A0A 50%, #0C0F14 100%);
    }
    .hero-bg-grid {
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
      background-size: 80px 80px;
    }
    .hero-bg-glow {
      position: absolute;
      width: 700px;
      height: 700px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(37,99,235,0.12) 0%, transparent 70%);
      top: -200px;
      right: -150px;
      pointer-events: none;
    }

    .hero-slides {
      position: relative;
      z-index: 1;
      padding: 80px 0 0;
    }

    .hero-slide {
      display: none;
      padding-bottom: 80px;
    }
    .hero-slide.active { display: block; }

    .hero-eyebrow {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 20px;
    }

    .hero-title {
      font-size: clamp(2.5rem, 6.5vw, 5.5rem);
      font-weight: 900;
      line-height: 1.0;
      letter-spacing: -0.035em;
      max-width: 900px;
      margin-bottom: 24px;
    }

    .hero-body {
      font-size: clamp(1rem, 1.5vw, 1.1875rem);
      color: var(--gray-400);
      max-width: 560px;
      line-height: 1.7;
      margin-bottom: 40px;
    }

    .hero-controls {
      position: relative;
      z-index: 1;
      border-top: 1px solid var(--border);
      padding: 24px 0;
    }
    .hero-controls-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }
    .hero-dots {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .hero-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--gray-600);
      border: none;
      cursor: pointer;
      padding: 0;
      transition: all 0.25s;
    }
    .hero-dot.active {
      background: var(--white);
      width: 24px;
      border-radius: 3px;
    }
    .hero-nav-btns {
      display: flex;
      gap: 8px;
    }
    .hero-nav-btn {
      width: 40px;
      height: 40px;
      border: 1px solid var(--border);
      background: none;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      color: var(--gray-400);
      transition: all 0.2s;
      font-size: 16px;
    }
    .hero-nav-btn:hover { border-color: var(--white); color: var(--white); background: rgba(255,255,255,0.04); }

    .hero-progress {
      font-size: 12px;
      color: var(--gray-500);
      font-variant-numeric: tabular-nums;
    }

    /* ── TEAM CAROUSEL ── */
    #team {
      padding: 120px 0;
      background: var(--bg);
      border-top: 1px solid var(--border);
    }

    .section-header {
      display: flex;
      flex-direction: column;
      gap: 16px;
      margin-bottom: 56px;
    }
    @media (min-width: 768px) {
      .section-header {
        flex-direction: row;
        align-items: flex-end;
        justify-content: space-between;
      }
      .section-header-text { flex: 1; }
    }

    .region-tabs {
      display: flex;
      gap: 4px;
      background: var(--bg-3);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 4px;
      flex-wrap: wrap;
      margin-bottom: 48px;
    }
    .region-tab {
      padding: 9px 20px;
      border-radius: 4px;
      border: none;
      background: none;
      color: var(--gray-400);
      font-size: 13px;
      font-weight: 500;
      font-family: inherit;
      cursor: pointer;
      transition: all 0.2s;
      white-space: nowrap;
    }
    .region-tab:hover { color: var(--white); }
    .region-tab.active {
      background: var(--white);
      color: #000;
      font-weight: 600;
    }

    .team-region { display: none; }
    .team-region.active { display: block; }

    .team-track-wrapper {
      position: relative;
      overflow: hidden;
    }
    .team-track {
      display: flex;
      gap: 24px;
      transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }
    .team-card {
      flex: 0 0 calc(50% - 12px);
      min-width: 280px;
      background: var(--bg-2);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      transition: border-color 0.25s;
    }
    @media (min-width: 768px) { .team-card { flex: 0 0 calc(33.333% - 16px); } }
    @media (min-width: 1200px) { .team-card { flex: 0 0 calc(25% - 18px); min-width: unset; } }
    .team-card:hover { border-color: var(--border-hover); }

    .team-photo {
      width: 100%;
      aspect-ratio: 4/3;
      background: var(--bg-3);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .team-photo-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .team-avatar {
      width: 72px;
      height: 72px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--bg-2) 0%, var(--gray-600) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      font-weight: 800;
      color: var(--gray-400);
      letter-spacing: -0.02em;
    }
    .team-photo-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to bottom, transparent 50%, rgba(0,0,0,0.4) 100%);
    }

    .team-card-body {
      padding: 20px 20px 24px;
    }
    .team-quote {
      font-size: 13.5px;
      line-height: 1.65;
      color: var(--gray-400);
      font-style: italic;
      margin-bottom: 20px;
      quotes: "\201C" "\201D";
    }
    .team-quote::before { content: open-quote; }
    .team-quote::after { content: close-quote; }

    .team-meta { border-top: 1px solid var(--border); padding-top: 16px; }
    .team-name { font-size: 15px; font-weight: 700; margin-bottom: 2px; }
    .team-title-role { font-size: 12px; color: var(--gray-500); margin-bottom: 12px; }
    .team-cta {
      font-size: 12px;
      font-weight: 600;
      color: var(--accent);
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 5px;
      transition: gap 0.2s;
    }
    .team-cta:hover { gap: 8px; }

    .team-carousel-controls {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-top: 32px;
    }
    .carousel-btn {
      width: 44px;
      height: 44px;
      border: 1px solid var(--border);
      background: none;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      color: var(--gray-400);
      font-size: 18px;
      transition: all 0.2s;
      font-family: inherit;
    }
    .carousel-btn:hover { border-color: var(--white); color: var(--white); }
    .carousel-btn:disabled { opacity: 0.3; cursor: default; }
    .carousel-btn-group { display: flex; gap: 8px; }

    /* ── WORK SHOWCASE ── */
    #work {
      padding: 120px 0;
      border-top: 1px solid var(--border);
      overflow: hidden;
    }

    .work-track-wrapper {
      position: relative;
      margin-top: 56px;
      overflow: hidden;
    }
    .work-track {
      display: flex;
      gap: 24px;
      transition: transform 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      padding-bottom: 8px;
    }
    .work-card {
      flex: 0 0 320px;
      background: var(--bg-2);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      transition: border-color 0.25s, transform 0.25s;
    }
    @media (min-width: 768px) { .work-card { flex: 0 0 380px; } }
    @media (min-width: 1024px) { .work-card { flex: 0 0 420px; } }
    .work-card:hover { border-color: var(--border-hover); transform: translateY(-3px); }

    .work-thumbnail {
      width: 100%;
      aspect-ratio: 16/10;
      background: var(--bg-3);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .work-thumb-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .work-thumb-logo {
      font-size: 28px;
      font-weight: 900;
      letter-spacing: -0.04em;
      opacity: 0.15;
    }

    .work-card-body { padding: 24px; }
    .work-client { font-size: 11px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--accent); margin-bottom: 8px; }
    .work-project-title { font-size: 17px; font-weight: 700; line-height: 1.35; margin-bottom: 12px; }
    .work-quote { font-size: 13px; color: var(--gray-400); line-height: 1.6; margin-bottom: 16px; font-style: italic; }
    .work-quote-attr { font-size: 11px; color: var(--gray-500); }

    .work-controls {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-top: 32px;
    }

    /* ── CTA BANNER ── */
    #cta-banner {
      padding: 100px 0;
      background: linear-gradient(135deg, #0D1B4A 0%, #0A0A0A 100%);
      border-top: 1px solid rgba(37,99,235,0.2);
      border-bottom: 1px solid rgba(37,99,235,0.2);
    }
    .cta-banner-inner {
      display: flex;
      flex-direction: column;
      gap: 40px;
      align-items: flex-start;
    }
    @media (min-width: 768px) {
      .cta-banner-inner {
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
      }
    }
    .cta-banner-title { font-size: clamp(2rem, 4vw, 3rem); font-weight: 900; letter-spacing: -0.03em; line-height: 1.1; }
    .cta-banner-body { font-size: 1rem; color: var(--gray-400); max-width: 520px; line-height: 1.7; margin-top: 16px; }

    /* ── HOW WE WORK ── */
    #how-we-work {
      padding: 120px 0;
      border-top: 1px solid var(--border);
    }
    .how-we-work-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 64px;
      align-items: center;
    }
    @media (min-width: 1024px) {
      .how-we-work-grid { grid-template-columns: 1fr 1fr; }
    }

    .how-visual {
      background: var(--bg-2);
      border: 1px solid var(--border);
      border-radius: 16px;
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .how-visual-inner {
      text-align: center;
      color: var(--gray-600);
    }
    .how-visual-circles {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .how-circle {
      position: absolute;
      border-radius: 50%;
      border: 1px solid rgba(37,99,235,0.2);
    }
    .how-circle:nth-child(1) { width: 80px; height: 80px; background: rgba(37,99,235,0.12); }
    .how-circle:nth-child(2) { width: 160px; height: 160px; }
    .how-circle:nth-child(3) { width: 260px; height: 260px; }
    .how-circle:nth-child(4) { width: 380px; height: 380px; opacity: 0.5; }

    .how-label { position: relative; z-index: 1; font-size: 13px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent); }

    .how-content-label { margin-bottom: 16px; }
    .how-title { font-size: clamp(2rem, 3.5vw, 2.75rem); font-weight: 900; letter-spacing: -0.03em; line-height: 1.1; margin-bottom: 24px; }
    .how-body { font-size: 1.0625rem; color: var(--gray-400); line-height: 1.75; margin-bottom: 36px; }

    /* ── INSIGHTS ── */
    #insights {
      padding: 120px 0;
      border-top: 1px solid var(--border);
    }

    .insights-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 1px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      margin-top: 56px;
    }
    @media (min-width: 640px) { .insights-grid { grid-template-columns: 1fr 1fr; } }
    @media (min-width: 1024px) { .insights-grid { grid-template-columns: repeat(4, 1fr); } }

    .insight-card {
      background: var(--bg-2);
      padding: 28px;
      display: flex;
      flex-direction: column;
      gap: 16px;
      transition: background 0.2s;
      text-decoration: none;
      color: inherit;
    }
    .insight-card:hover { background: var(--bg-3); }

    .insight-type-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 4px 10px;
      border-radius: 100px;
      width: fit-content;
    }
    .badge-podcast { background: rgba(245,158,11,0.12); color: var(--amber); }
    .badge-article { background: rgba(37,99,235,0.12); color: var(--accent-hover); }
    .badge-report { background: rgba(168,85,247,0.12); color: #A855F7; }

    .insight-title {
      font-size: 15px;
      font-weight: 700;
      line-height: 1.4;
      color: var(--white);
      flex: 1;
    }

    .insight-cta {
      font-size: 12px;
      font-weight: 600;
      display: flex;
      align-items: center;
      gap: 5px;
      transition: gap 0.2s;
    }
    .insight-cta-listen { color: var(--amber); }
    .insight-cta-read { color: var(--accent-hover); }
    .insight-cta-download { color: #A855F7; }
    .insight-card:hover .insight-cta { gap: 8px; }

    /* ── PRINCIPLES ── */
    #principles {
      padding: 120px 0;
      border-top: 1px solid var(--border);
      background: var(--bg-2);
    }

    .principles-header { margin-bottom: 80px; }
    .principles-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 48px;
    }
    @media (min-width: 768px) { .principles-grid { grid-template-columns: 1fr 1fr; gap: 56px 80px; } }

    .principle-num {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 16px;
    }
    .principle-divider {
      width: 40px;
      height: 1px;
      background: var(--accent);
      margin-bottom: 20px;
    }
    .principle-title {
      font-size: 1.375rem;
      font-weight: 800;
      line-height: 1.25;
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }
    .principle-body {
      font-size: 14.5px;
      color: var(--gray-400);
      line-height: 1.75;
    }

    /* ── FOOTER ── */
    footer {
      background: var(--bg);
      border-top: 1px solid var(--border);
      padding: 80px 0 40px;
    }

    .footer-ctas {
      display: grid;
      grid-template-columns: 1fr;
      gap: 1px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: 12px;
      overflow: hidden;
      margin-bottom: 80px;
    }
    @media (min-width: 768px) { .footer-ctas { grid-template-columns: 1fr 1fr; } }

    .footer-cta-block {
      background: var(--bg-2);
      padding: 48px;
      display: flex;
      flex-direction: column;
      gap: 24px;
    }
    .footer-cta-text { font-size: 1.0625rem; color: var(--gray-400); line-height: 1.65; max-width: 360px; }

    .footer-bottom {
      display: flex;
      flex-direction: column;
      gap: 32px;
    }
    @media (min-width: 768px) {
      .footer-bottom {
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
      }
    }

    .footer-logo {
      font-size: 22px;
      font-weight: 900;
      letter-spacing: -0.03em;
      color: var(--white);
      margin-bottom: 4px;
    }
    .footer-logo span { color: var(--accent); }
    .footer-tagline { font-size: 12px; color: var(--gray-500); }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 24px;
      list-style: none;
    }
    .footer-links a {
      font-size: 13px;
      color: var(--gray-500);
      text-decoration: none;
      transition: color 0.2s;
    }
    .footer-links a:hover { color: var(--white); }

    .footer-legal {
      border-top: 1px solid var(--border);
      padding-top: 32px;
      margin-top: 16px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    @media (min-width: 768px) {
      .footer-legal {
        flex-direction: row;
        justify-content: space-between;
        align-items: center;
      }
    }
    .footer-legal p { font-size: 12px; color: var(--gray-600); }
    .footer-legal-links {
      display: flex;
      flex-wrap: wrap;
      gap: 16px;
    }
    .footer-legal-links a {
      font-size: 12px;
      color: var(--gray-600);
      text-decoration: none;
      transition: color 0.2s;
    }
    .footer-legal-links a:hover { color: var(--gray-400); }

    /* ── COOKIE BANNER ── */
    #cookie-banner {
      position: fixed;
      bottom: 0; left: 0; right: 0;
      z-index: 9999;
      background: var(--bg-3);
      border-top: 1px solid var(--border);
      padding: 20px 24px;
      transform: translateY(0);
      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    }
    #cookie-banner.hidden { transform: translateY(100%); }
    .cookie-inner {
      max-width: 1320px;
      margin: 0 auto;
      display: flex;
      flex-direction: column;
      gap: 16px;
      align-items: flex-start;
    }
    @media (min-width: 768px) {
      .cookie-inner {
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
      }
    }
    .cookie-text { font-size: 13px; color: var(--gray-400); line-height: 1.6; max-width: 600px; }
    .cookie-text a { color: var(--white); text-decoration: underline; }
    .cookie-actions { display: flex; gap: 10px; flex-shrink: 0; flex-wrap: wrap; }
    .cookie-btn {
      padding: 9px 18px;
      border-radius: var(--radius);
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      border: none;
      font-family: inherit;
      transition: all 0.2s;
    }
    .cookie-accept { background: var(--white); color: #000; }
    .cookie-accept:hover { background: #E5E7EB; }
    .cookie-decline { background: transparent; color: var(--gray-400); border: 1px solid var(--border); }
    .cookie-decline:hover { color: var(--white); border-color: var(--border-hover); }
    .cookie-settings { background: transparent; color: var(--accent-hover); border: 1px solid rgba(37,99,235,0.3); }
    .cookie-settings:hover { border-color: var(--accent); }

    /* ── SLIDE-IN ANIMATION ── */
    .fade-up {
      opacity: 0;
      transform: translateY(32px);
      transition: opacity 0.6s ease, transform 0.6s ease;
    }
    .fade-up.visible { opacity: 1; transform: translateY(0); }
    .fade-up-delay-1 { transition-delay: 0.1s; }
    .fade-up-delay-2 { transition-delay: 0.2s; }
    .fade-up-delay-3 { transition-delay: 0.3s; }

    /* ── THUMB COLORS per project ── */
    .thumb-unilever   { background: linear-gradient(135deg, #1a2744 0%, #0D1117 100%); }
    .thumb-ikea       { background: linear-gradient(135deg, #1a2200 0%, #0A0A0A 100%); }
    .thumb-volvo      { background: linear-gradient(135deg, #001f44 0%, #0A0A0A 100%); }
    .thumb-chase      { background: linear-gradient(135deg, #111e3c 0%, #0A0A0A 100%); }
    .thumb-tiffany    { background: linear-gradient(135deg, #003c3c 0%, #0A0A0A 100%); }
    .thumb-carrefour  { background: linear-gradient(135deg, #2a0000 0%, #0A0A0A 100%); }
    .thumb-robots     { background: linear-gradient(135deg, #1a0a2e 0%, #0A0A0A 100%); }
    .thumb-nsw        { background: linear-gradient(135deg, #002244 0%, #0A0A0A 100%); }

    /* Team photo tones */
    .team-photo-na1 { background: linear-gradient(135deg, #1c1c2e 0%, #2d2d3e 100%); }
    .team-photo-na2 { background: linear-gradient(135deg, #1e2a1e 0%, #2e3e2e 100%); }
